#!/usr/bin/env node
/**
 * 零外部依赖的确定性 CommonJS 打包器：
 * 将 src/ 下的模块化源码打包为单个可直接放入 Obsidian 运行的 main.js，
 * 保留外部依赖 require("obsidian") 与 Node 内置模块（child_process/fs/path/crypto/util）。
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, "..");
const srcDir = path.join(rootDir, "src");
const outFile = path.join(rootDir, "main.js");

function collectModules(dir, base = dir) {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...collectModules(full, base));
    } else if (entry.name.endsWith(".js")) {
      const rel = "./" + path.relative(base, full).replace(/\\/g, "/");
      files.push({ id: rel, full });
    }
  }
  return files.sort((a, b) => a.id.localeCompare(b.id));
}

const modules = collectModules(srcDir);
const registryEntries = [];

for (const mod of modules) {
  const code = fs.readFileSync(mod.full, "utf8");
  const modDir = path.posix.dirname(mod.id);
  registryEntries.push(
    `  ${JSON.stringify(mod.id)}: [function(require, module, exports) {\n${code}\n  }, ${JSON.stringify(modDir)}]`
  );
}

const bundle = `/* THIS IS A GENERATED/BUNDLED FILE BY scripts/build.mjs — DO NOT EDIT DIRECTLY */
"use strict";

const __owb_modules = {
${registryEntries.join(",\n")}
};

const __owb_cache = Object.create(null);

function __owb_resolve(baseDir, request) {
  if (!request.startsWith(".")) return null;
  const parts = (baseDir === "." ? request : baseDir + "/" + request).split("/");
  const stack = [];
  for (const p of parts) {
    if (!p || p === ".") continue;
    if (p === "..") stack.pop();
    else stack.push(p);
  }
  const normalized = "./" + stack.join("/");
  if (__owb_modules[normalized]) return normalized;
  if (__owb_modules[normalized + ".js"]) return normalized + ".js";
  if (__owb_modules[normalized + "/index.js"]) return normalized + "/index.js";
  throw new Error("OWB bundle: cannot resolve module " + request + " from " + baseDir);
}

function __owb_require(id) {
  if (__owb_cache[id]) return __owb_cache[id].exports;
  const entry = __owb_modules[id];
  if (!entry) throw new Error("OWB bundle: unknown module " + id);
  const mod = { exports: {} };
  __owb_cache[id] = mod;
  const [factory, dir] = entry;
  const localRequire = (req) => {
    const resolved = __owb_resolve(dir, req);
    return resolved ? __owb_require(resolved) : require(req);
  };
  factory(localRequire, mod, mod.exports);
  return mod.exports;
}

module.exports = __owb_require("./main.js");
`;

fs.writeFileSync(outFile, bundle, "utf8");
console.log(`Built ${outFile} (${modules.length} modules, ${Buffer.byteLength(bundle, "utf8")} bytes)`);
